allow:
command(powershell -Command "
$gitCmd = Get-Command git -ErrorAction SilentlyContinue
if ($gitCmd) {
    Write-Host '=== Git in PATH ==='
    Write-Host ('Source: ' + $gitCmd.Source)
    & git --version
} else {
    Write-Host '=== Git not found in PATH ==='
}

Write-Host '`n=== Checking Common Locations ==='
$locations = @(
    '$env:ProgramFiles\Git\cmd\git.exe',
    '${env:ProgramFiles(x86)}\Git\cmd\git.exe',
    '$env:LOCALAPPDATA\Programs\Git\cmd\git.exe',
    '$env:LOCALAPPDATA\GitHubDesktop',
    '$env:ProgramFiles\TortoiseGit\bin\TortoiseGitProc.exe'
)
foreach ($loc in $locations) {
    $expanded = $ExecutionContext.InvokeCommand.ExpandString($loc)
    if (Test-Path $expanded) {
        Write-Host ('Found: ' + $expanded)
    }
}
")
